// Generated by scripts/sync-update-workflow.mjs from .github/workflows/update-from-kledg.yml. Do not edit.
export const UPDATE_WORKFLOW = "# Keeps a self-hosted copy of Kledg up to date.\n# kledg-workflow-version: 2 (lib/updates/service.ts upgrades older files)\n#\n# The \"Deploy to Vercel\" button creates a copy of kledghq/kledg that is not a\n# GitHub fork, so GitHub's \"Sync fork\" button is not available. This workflow\n# runs in YOUR copy: every week it fetches Kledg and opens (or refreshes) a\n# pull request. Hosts that deploy from GitHub (Vercel, Railway, Render...) may\n# build a preview of it; merge it to update your instance (they redeploy and\n# run the migrations; with Docker, pull and rebuild on the server). It never runs\n# in kledghq/kledg itself. The Kledg \"Mises à jour\" page can also start it.\n#\n# A copy made by the Vercel button starts with a single commit (a snapshot of\n# Kledg) that shares no history with kledghq/kledg, so a plain `git merge`\n# refuses it. The first update attaches Kledg's history once: it finds the\n# Kledg commit the snapshot was made from and records it as merged with the\n# \"ours\" strategy (no file changes), then merges the update normally. Your own\n# changes since the copy are kept and merged like in a fork.\n#\n# GitHub does not let this workflow's token push changes to workflow files.\n# Unless the secret KLEDG_UPDATE_TOKEN holds a token with the Workflows\n# permission, the update keeps your .github/workflows files as they are (the\n# Kledg \"Mises à jour\" page updates this file with its own token).\n#\n# Choose what to follow with the repository variable KLEDG_UPDATES\n# (Settings > Secrets and variables > Actions > Variables):\n#   releases  (default) only published releases, with their release notes\n#   main      every change on kledghq/kledg main, for testers\n#   off       never open update pull requests\n\nname: Update from Kledg\n\non:\n  schedule:\n    - cron: \"0 6 * * 1\" # Mondays 06:00 UTC\n  workflow_dispatch:\n\npermissions:\n  contents: write\n  pull-requests: write\n\nconcurrency:\n  group: update-from-kledg\n  cancel-in-progress: true\n\njobs:\n  update:\n    if: github.repository != 'kledghq/kledg' && vars.KLEDG_UPDATES != 'off'\n    runs-on: ubuntu-latest\n    env:\n      UPSTREAM: https://github.com/kledghq/kledg.git\n      CHANNEL: ${{ vars.KLEDG_UPDATES || 'releases' }}\n      BRANCH: kledg-update\n      GH_TOKEN: ${{ github.token }}\n    steps:\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7\n        with:\n          fetch-depth: 0\n          token: ${{ secrets.KLEDG_UPDATE_TOKEN || github.token }}\n\n      - name: Fetch Kledg\n        id: fetch\n        run: |\n          git remote add upstream \"$UPSTREAM\"\n          case \"$CHANNEL\" in\n            releases)\n              TAG=$(gh api repos/kledghq/kledg/releases/latest --jq .tag_name 2>/dev/null || true)\n              if [ -z \"$TAG\" ]; then\n                echo \"No published Kledg release yet.\"\n                echo \"ref=\" >> \"$GITHUB_OUTPUT\"\n                exit 0\n              fi\n              # A tag name is data: only the characters of a version tag go further\n              case \"$TAG\" in\n                *[!A-Za-z0-9._-]*)\n                  echo \"::error::Unexpected Kledg release tag.\"\n                  exit 1\n                  ;;\n              esac\n              git fetch upstream \"refs/tags/$TAG:refs/tags/$TAG\"\n              echo \"ref=refs/tags/$TAG\" >> \"$GITHUB_OUTPUT\"\n              echo \"label=$TAG\" >> \"$GITHUB_OUTPUT\"\n              echo \"notes=https://github.com/kledghq/kledg/releases/tag/$TAG\" >> \"$GITHUB_OUTPUT\"\n              ;;\n            main)\n              git fetch upstream main\n              VERSION=$(git show upstream/main:package.json | jq -r .version)\n              echo \"ref=upstream/main\" >> \"$GITHUB_OUTPUT\"\n              echo \"label=$VERSION ($(git rev-parse --short upstream/main))\" >> \"$GITHUB_OUTPUT\"\n              echo \"notes=https://github.com/kledghq/kledg/commits/main\" >> \"$GITHUB_OUTPUT\"\n              ;;\n            *)\n              echo \"::error::KLEDG_UPDATES must be releases, main or off (got \\\"$CHANNEL\\\").\"\n              exit 1\n              ;;\n          esac\n\n      - name: Check for new commits\n        id: check\n        if: steps.fetch.outputs.ref != ''\n        env:\n          # Expressions never go inside a script: the value comes through the environment\n          REF: ${{ steps.fetch.outputs.ref }}\n        run: |\n          if git merge-base --is-ancestor \"$REF\" HEAD; then\n            echo \"Already up to date.\"\n            echo \"changes=false\" >> \"$GITHUB_OUTPUT\"\n          else\n            echo \"changes=true\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n      - name: Prepare the update branch\n        id: prepare\n        if: steps.check.outputs.changes == 'true'\n        env:\n          REF: ${{ steps.fetch.outputs.ref }}\n          BASE: ${{ github.event.repository.default_branch }}\n          HAS_WORKFLOW_TOKEN: ${{ secrets.KLEDG_UPDATE_TOKEN != '' }}\n        run: |\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"41898282+github-actions[bot]@users.noreply.github.com\"\n          git checkout -B \"$BRANCH\"\n          # BEGIN kledg-merge (tested by lib/updates/__tests__/workflow-merge.test.ts)\n          fail() {\n            echo \"::error::$1 Voir docs/self-hosting.md#mettre-à-jour\"\n            exit 1\n          }\n          # Conflicts only in workflow files: keep ours, unless a token may push\n          # workflow changes (then take Kledg's).\n          resolve_workflow_conflicts() {\n            CONFLICTS=$(git diff --name-only --diff-filter=U)\n            [ -n \"$CONFLICTS\" ] || return 1\n            if printf '%s\\n' \"$CONFLICTS\" | grep -qv '^\\.github/workflows/'; then return 1; fi\n            for f in $CONFLICTS; do\n              if [ \"$HAS_WORKFLOW_TOKEN\" = \"true\" ] && git cat-file -e \"MERGE_HEAD:$f\" 2>/dev/null; then\n                git checkout --theirs -- \"$f\" && git add -- \"$f\"\n              elif [ \"$HAS_WORKFLOW_TOKEN\" != \"true\" ] && git cat-file -e \"HEAD:$f\" 2>/dev/null; then\n                git checkout --ours -- \"$f\" && git add -- \"$f\"\n              else\n                git rm -q -- \"$f\"\n              fi\n            done\n            git commit -q --no-edit\n          }\n          if ! git merge-base HEAD \"$REF\" >/dev/null 2>&1; then\n            # A copy made by the Vercel button: unrelated history. Find the\n            # Kledg commit its first commit is a snapshot of (ignoring .github,\n            # which the copy may lack) and record it as merged, without\n            # changing any file.\n            git fetch --quiet upstream main\n            ROOT=$(git rev-list --max-parents=0 HEAD | tail -n 1)\n            ROOT_TIME=$(git log -1 --format=%ct \"$ROOT\")\n            CANDIDATES=$(git rev-list --max-count=500 --before=\"@$((ROOT_TIME + 3600))\" upstream/main \"$REF\")\n            [ -n \"$CANDIDATES\" ] || CANDIDATES=$(git rev-list --max-count=500 upstream/main \"$REF\")\n            ADOPT=\"\"\n            ADOPT_COUNT=\"\"\n            for C in $CANDIDATES; do\n              COUNT=$(git diff --name-only \"$C\" \"$ROOT\" -- . ':(exclude).github' | wc -l | tr -d ' ')\n              if [ -z \"$ADOPT_COUNT\" ] || [ \"$COUNT\" -lt \"$ADOPT_COUNT\" ]; then\n                ADOPT=$C\n                ADOPT_COUNT=$COUNT\n              fi\n              if [ \"$COUNT\" -eq 0 ]; then break; fi\n            done\n            [ -n \"$ADOPT\" ] || fail \"Impossible de rattacher votre copie à l'historique de Kledg.\"\n            echo \"Copy made from Kledg $ADOPT ($ADOPT_COUNT files differ outside .github).\"\n            git merge -q -s ours --allow-unrelated-histories -m \"Attach Kledg history (copy made from $(git rev-parse --short \"$ADOPT\"))\" \"$ADOPT\"\n            echo \"adopted=$ADOPT\" >> \"$GITHUB_OUTPUT\"\n          fi\n          if ! git merge --no-edit \"$REF\"; then\n            resolve_workflow_conflicts || fail \"Votre copie contient des modifications en conflit avec Kledg : fusionnez à la main.\"\n          fi\n          if [ \"$HAS_WORKFLOW_TOKEN\" != \"true\" ]; then\n            KEPT=$(git diff --name-only \"origin/$BASE\" HEAD -- .github/workflows)\n            if [ -n \"$KEPT\" ]; then\n              for f in $KEPT; do\n                if git cat-file -e \"origin/$BASE:$f\" 2>/dev/null; then\n                  git checkout \"origin/$BASE\" -- \"$f\"\n                else\n                  git rm -q --cached -- \"$f\"\n                  rm -f -- \"$f\"\n                fi\n              done\n              git commit -q -m \"Keep this repository's workflow files\"\n              echo \"workflows_kept=$(printf '%s' \"$KEPT\" | tr '\\n' ' ')\" >> \"$GITHUB_OUTPUT\"\n            fi\n          fi\n          # END kledg-merge\n          git push --force origin \"$BRANCH\"\n\n      - name: Open or refresh the pull request\n        if: steps.check.outputs.changes == 'true'\n        env:\n          LABEL: ${{ steps.fetch.outputs.label }}\n          NOTES: ${{ steps.fetch.outputs.notes }}\n          BASE: ${{ github.event.repository.default_branch }}\n          ADOPTED: ${{ steps.prepare.outputs.adopted }}\n          WORKFLOWS_KEPT: ${{ steps.prepare.outputs.workflows_kept }}\n          REPO_URL: ${{ github.server_url }}/${{ github.repository }}\n        run: |\n          MIGRATIONS=$(git diff --name-only --diff-filter=A \"origin/$BASE\" \"$BRANCH\" -- prisma/migrations \\\n            | grep '/migration.sql$' | sed 's#^prisma/migrations/##; s#/migration.sql$##; s#^#- #' || true)\n          if [ -n \"$MIGRATIONS\" ]; then\n            MIGRATION_TEXT=$(printf 'Migrations de la base appliquées au déploiement :\\n\\n%s\\n\\nPensez à sauvegarder la base avant de fusionner (Neon : créez une branche de sauvegarde ; ailleurs, vérifiez la dernière sauvegarde de votre hébergeur).' \"$MIGRATIONS\")\n          else\n            MIGRATION_TEXT=\"Aucune migration de la base.\"\n          fi\n          EXTRA=\"\"\n          if [ -n \"$ADOPTED\" ]; then\n            EXTRA=$(printf '%s\\n\\nPremière mise à jour de cette copie : elle est rattachée à l%shistorique de Kledg (copie faite depuis %s), sans modifier vos fichiers.' \"$EXTRA\" \"'\" \"$ADOPTED\")\n          fi\n          if [ -n \"$WORKFLOWS_KEPT\" ]; then\n            EXTRA=$(printf '%s\\n\\nFichiers de workflow conservés tels quels (le jeton des Actions ne peut pas les modifier) : %s' \"$EXTRA\" \"$WORKFLOWS_KEPT\")\n          fi\n          BODY=$(printf 'Mise à jour vers Kledg %s.\\n\\nNotes : %s\\n\\n%s%s\\n\\nSi votre hébergeur construit des aperçus (Vercel, Railway, Render), vérifiez celui de cette pull request. Fusionnez-la ensuite pour mettre à jour votre instance : un hébergeur qui déploie depuis GitHub la redéploie et applique les migrations.' \"$LABEL\" \"$NOTES\" \"$MIGRATION_TEXT\" \"$EXTRA\")\n          TITLE=\"Mise à jour Kledg $LABEL\"\n          if gh pr view \"$BRANCH\" --json state -q .state 2>/dev/null | grep -q OPEN; then\n            gh pr edit \"$BRANCH\" --title \"$TITLE\" --body \"$BODY\"\n          else\n            if ! gh pr create --head \"$BRANCH\" --base \"$BASE\" --title \"$TITLE\" --body \"$BODY\"; then\n              # Repositories can forbid Actions from opening pull requests\n              # (Settings > Actions > General). The branch is pushed anyway.\n              URL=\"$REPO_URL/compare/$BASE...$BRANCH?expand=1\"\n              echo \"::warning::Ouvrez la mise à jour en un clic : $URL\"\n              echo \"Ouvrez la mise à jour : $URL\" >> \"$GITHUB_STEP_SUMMARY\"\n            fi\n          fi\n"
